import { readFile } from "node:fs/promises";
import path from "node:path";
import { createClient } from "@supabase/supabase-js";

export const dynamic = "force-dynamic";

type WikiResult = {
  html: string | null;
  age: number | null;
  error: "missing_supabase_url" | "missing_service_key" | "query_failed" | "no_approved_row" | "exception" | null;
};

// Newest approved wiki generated by the age-update flow.
// Keep diagnostics categorical: never expose raw database or exception messages.
async function latestWikiFromDb(): Promise<WikiResult> {
  const url = process.env.NEXT_PUBLIC_SUPABASE_URL;
  const key = process.env.SUPABASE_SERVICE_ROLE_KEY || process.env.SUPABASE_SECRET_KEY;
  if (!url) return { html: null, age: null, error: "missing_supabase_url" };
  if (!key) return { html: null, age: null, error: "missing_service_key" };

  try {
    const supabase = createClient(url, key, {
      auth: { autoRefreshToken: false, persistSession: false },
    });
    const { data, error } = await supabase
      .from("spartan_wiki")
      .select("content_html,age_number")
      .eq("document_key", "utopia-reference")
      .eq("approved", true)
      .order("age_number", { ascending: false })
      .limit(1)
      .maybeSingle();

    if (error) return { html: null, age: null, error: "query_failed" };
    if (!data?.content_html) return { html: null, age: null, error: "no_approved_row" };

    const age = typeof data.age_number === "number" ? data.age_number : null;
    return { html: data.content_html as string, age, error: null };
  } catch {
    return { html: null, age: null, error: "exception" };
  }
}

export async function GET(request: Request) {
  const db = await latestWikiFromDb();
  let html = db.html;
  const source: "db" | "file" = db.html ? "db" : "file";
  let age = db.html ? db.age : null;

  if (!html) {
    console.error("[WIKI ROUTE] Using bundled wiki fallback:", db.error ?? "unknown");
    const wikiPath = path.join(process.cwd(), "lib", "spartan", "knowledge", "utopia-reference.html");
    html = await readFile(wikiPath, "utf8");
    const bundledAge = html.match(/\bage[\s_-]*(\d{2,3})\b/i);
    age = bundledAge ? Number(bundledAge[1]) : null;
  }

  if (new URL(request.url).searchParams.get("debug") === "1") {
    return new Response(
      `source: ${source}\nage: ${age ?? "unknown"}\nerror: ${db.error ?? "none"}\nchars: ${html.length}\n`,
      {
        status: 200,
        headers: {
          "Content-Type": "text/plain; charset=utf-8",
          "Cache-Control": "no-store",
        },
      },
    );
  }

  return new Response(html, {
    status: 200,
    headers: {
      "Content-Type": "text/html; charset=utf-8",
      "Cache-Control": "public, max-age=60, s-maxage=60, stale-while-revalidate=300",
      "X-Wiki-Source": source,
    },
  });
}
